/* 1) 基本用法 */
await ssp.objectsTool.flyToFloor?.('A_6F');  // API 没这个便捷方法, 用以下:

const FLOOR = 'A_6F';
const targets = ssp.objectsTool.getByUserDataProperty('floorName', FLOOR);
if (targets.length > 0) {
  await ssp.cameraController.flyToObject(targets[0]);
  console.log(`flew to ${FLOOR}`);
}

/* 2) 限定 subcategory (避免同名 floor 跨子目录冲突) */
const targets2 = ssp.objectsTool.getByUserDataProperty('floorName', 'A_6F', { scope: 'hospital' });
if (targets2.length > 0) await ssp.cameraController.flyToObject(targets2[0]);

/* 3) 无动画瞬移 */
const t = ssp.objectsTool.getByUserDataProperty('floorName', 'A_15F')[0];
if (t) await ssp.cameraController.flyToObject(t, { enableTransition: false });

/* 4) 楼层定位 + 飞行 完成回调 */
const fl = ssp.objectsTool.getByUserDataProperty('floorName', 'B_6F')[0];
if (fl) {
  await ssp.cameraController.flyToObject(fl, {
    enableTransition: true,
    done: () => console.log('arrived at B_6F'),
  });
}
